#include <bits/stdc++.h>
using namespace std;
using ll=long long;
const ll MOD=998244353;
bool validstate(int n,int x,int l,bool left,const vector<int>& pos){
    int r=x-1-l;
    for(int i:pos){
        bool pre=false;
        int position;
        if(left)position=l+1;
        else position =n-x+1+l;
        if(position <=i){
            int smaller=min(i,l)+max(0,i+x-n-1-l);
            int need=(i-1)/2;
            if(smaller==need)pre=true;
            
        }
        bool suff=false;
        if(position >= i){
            int smaller=min(r,n-i+1)+max(0,l-i+1);
            int need=(n-i)/2;
            if(smaller==need)suff=true;
        }
        if(!pre&&!suff)return false;
    }
    return true;
} 
void solve() {
    int n;
    cin>>n;
    vector<int>a(n+1);
    vector<vector<int>>pos(n+1);
    for(int i=1;i<=n;i++){
        cin>>a[i];
        if(a[i]<1||a[i]>n){
            cout<<0<<endl;
            return;
        }
        pos[a[i]].push_back(i);
    }
    if(n==1){
        cout<<(a[1]==1?1:0)<<endl;
        return;
    }
    vector<ll>dp(n+1,0),ndp(n+1,0);
    dp[0]=1;
    for(int x=1;x<n;x++){
        fill(ndp.begin(),ndp.end(),0);
        for(int l=0;l<x;l++){
            if(dp[l]==0)continue;
            if(validstate(n,x,l,false,pos[x])){
                ndp[l]+=dp[l];
                if(ndp[l]>=MOD)ndp[l]-=MOD;
            }
            if(validstate(n,x,l,true,pos[x])){
                ndp[l+1]+=dp[l];
                if(ndp[l+1]>=MOD)ndp[l+1]-=MOD;
            }
        }
        dp.swap(ndp);
        
    }
    ll ans=0;
    for(int l=0;l<=n-1;l++){
        if(dp[l]==0)continue;
        bool ok=true;
        for(int i:pos[n]){
            if(i==1){
                if(l!=0){
                    ok=false;
                    break;
                }
            }else if(i==n){
                if(l!=n-1){
                    ok=false;
                    break;
                }
            }
            else{
                ok=false;
                break;
            }
        }
        if(ok){
            ans+=dp[l];
            if(ans>=MOD)ans-=MOD;
        }
    }
    cout<<ans<<endl;
}
int main() {
   int t;
   cin>>t;
   while(t--){
       solve();
   }

}
